	public ModelAndView getM_TOP_100_BORROWERView(String reportId, String fromdate, String todate, String currency,
			String dtltype, Pageable pageable, String type, BigDecimal version) {
		ModelAndView mv = new ModelAndView();
		String displaymode = "summary";

		try {
			Date reportDate = dateformat.parse(todate);

			// ================= ARCHIVAL / RESUB =================
			// Like the reference service, RESUB is an archived version viewed through
			// a different path; therefore both branches read the archival tables.
			if (("ARCHIVAL".equalsIgnoreCase(type) || "RESUB".equalsIgnoreCase(type)) && version != null) {
				List<M_TOP_100_BORROWER_Archival_Summary_Entity> T1Master = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_SUMMARY WHERE TRUNC(REPORT_DATE) = TRUNC(?) AND REPORT_VERSION = ?",
						M_TOP_100_BORROWER_Archival_Summary_Entity.class, reportDate, version);
				List<M_TOP_100_BORROWER_Manual_Archival_Summary_Entity1> T2Master = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_ARCHIVALTABLE_SUMMARY1 WHERE TRUNC(REPORT_DATE) = TRUNC(?) AND REPORT_VERSION = ?",
						M_TOP_100_BORROWER_Manual_Archival_Summary_Entity1.class, reportDate, version);
				List<M_TOP_100_BORROWER_Manual_Archival_Summary_Entity2> T3Master = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_ARCHIVALTABLE_SUMMARY2 WHERE TRUNC(REPORT_DATE) = TRUNC(?) AND REPORT_VERSION = ?",
						M_TOP_100_BORROWER_Manual_Archival_Summary_Entity2.class, reportDate, version);

				mv.addObject("reportsummary", T1Master);
				mv.addObject("reportsummary1", T2Master);
				mv.addObject("reportsummary2", T3Master);
				if ("RESUB".equalsIgnoreCase(type)) {
					displaymode = "resubSummary";
				}
			} else {
				// ================= CURRENT / LIVE =================
				List<M_TOP_100_BORROWER_Summary_Entity> T1Master = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_SUMMARYTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
						M_TOP_100_BORROWER_Summary_Entity.class, reportDate);
				List<M_TOP_100_BORROWER_Manual_Summary_Entity1> T2Master = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE1 WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
						M_TOP_100_BORROWER_Manual_Summary_Entity1.class, reportDate);
				List<M_TOP_100_BORROWER_Manual_Summary_Entity2> T3Master = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE2 WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
						M_TOP_100_BORROWER_Manual_Summary_Entity2.class, reportDate);

				mv.addObject("reportsummary", T1Master);
				mv.addObject("reportsummary1", T2Master);
				mv.addObject("reportsummary2", T3Master);
			}
		} catch (ParseException e) {
			logger.error("Invalid report date: {}", todate, e);
			mv.addObject("errorMessage", "Invalid date format: " + todate);
		} catch (Exception e) {
			logger.error("Error loading M_TOP_100_BORROWER summary", e);
			mv.addObject("errorMessage", "Unexpected error: " + e.getMessage());
		}

		mv.setViewName("BRRS/M_TOP_100_BORROWER");
		mv.addObject("displaymode", displaymode);
		mv.addObject("reportsflag", "reportsflag");
		mv.addObject("menu", reportId);
		return mv;
	}

	public ModelAndView getM_TOP_100_BORROWERcurrentDtl(String reportId, String fromdate, String todate,
			String currency, String dtltype, Pageable pageable, String Filter, String type, String version) {

		int pageSize = pageable != null ? pageable.getPageSize() : 10;
		int currentPage = pageable != null ? pageable.getPageNumber() : 0;
		int totalPages = 0;
		String displaymode = "Details";
		ModelAndView mv = new ModelAndView();

		try {
			Date parsedDate = (todate != null && !todate.isEmpty()) ? dateformat.parse(todate) : null;

			if (("ARCHIVAL".equalsIgnoreCase(type) || "RESUB".equalsIgnoreCase(type)) && version != null) {
				List<M_TOP_100_BORROWER_Archival_Detail_Entity> T1Dt1 = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_DETAIL WHERE TRUNC(REPORT_DATE) = TRUNC(?) AND DATA_ENTRY_VERSION = ?",
						M_TOP_100_BORROWER_Archival_Detail_Entity.class, parsedDate, version.toString());

				mv.addObject("reportdetails", T1Dt1);
				mv.addObject("reportmaster12", T1Dt1);
				if ("RESUB".equalsIgnoreCase(type)) {
					displaymode = "resubDetail";
				}
				logger.info("{} detail count: {}", type, T1Dt1 != null ? T1Dt1.size() : 0);
			} else {
				List<M_TOP_100_BORROWER_Detail_Entity> T1Dt1 = queryEntities(
						"SELECT * FROM BRRS_M_TOP_100_BORROWER_DETAILTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?) OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",
						M_TOP_100_BORROWER_Detail_Entity.class, parsedDate, currentPage * pageSize, pageSize);
				totalPages = jdbcTemplate.queryForObject(
						"SELECT COUNT(*) FROM BRRS_M_TOP_100_BORROWER_DETAILTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
						new Object[] { parsedDate }, Integer.class);
				mv.addObject("pagination", "YES");
				mv.addObject("reportdetails", T1Dt1);
				mv.addObject("reportmaster12", T1Dt1);
				logger.info("Current detail count: {}", T1Dt1 != null ? T1Dt1.size() : 0);
			}
		} catch (ParseException e) {
			logger.error("Invalid date format: {}", todate, e);
			mv.addObject("errorMessage", "Invalid date format: " + todate);
		} catch (Exception e) {
			logger.error("Error loading M_TOP_100_BORROWER details", e);
			mv.addObject("errorMessage", "Unexpected error: " + e.getMessage());
		}

		mv.setViewName("BRRS/M_TOP_100_BORROWER");
		mv.addObject("displaymode", displaymode);
		mv.addObject("currentPage", currentPage);
		mv.addObject("totalPages", pageSize > 0 ? (int) Math.ceil((double) totalPages / pageSize) : 0);
		mv.addObject("reportsflag", "reportsflag");
		mv.addObject("menu", reportId);
		return mv;
	}

	/**
	 * Compatibility overload matching the reference report service signature.
	 * The TOP-100 report uses the same workbook generation regardless of format;
	 * the format value is therefore accepted for controller compatibility.
	 */
	public byte[] getM_TOP_100_BORROWERExcel(String filename, String reportId, String fromdate, String todate,
			String currency, String dtltype, String type, String format, BigDecimal version) throws Exception {
		return getM_TOP_100_BORROWERExcel(filename, reportId, fromdate, todate, currency, dtltype, type, version);
	}

	public byte[] getM_TOP_100_BORROWERExcel(String filename, String reportId, String fromdate,
	        String todate, String currency, String dtltype, String type, BigDecimal version) throws Exception {

	    logger.info("Service: Starting Excel generation process in memory.");

	    // ✅ ARCHIVAL check
	    if (("ARCHIVAL".equalsIgnoreCase(type) || "RESUB".equalsIgnoreCase(type)) && version != null) {
	        logger.info("Service: Generating {} report for version {}", type, version);
	        return getExcelM_TOP_100_BORROWERARCHIVAL(filename, reportId, fromdate, todate,
	                currency, dtltype, type, version);
	    }

	    // ✅ Fetch data
	    Date reportDate = dateformat.parse(todate);
	    logger.info("Report date: {}", reportDate);

	    List<M_TOP_100_BORROWER_Summary_Entity> dataList = queryEntities(
	            "SELECT * FROM BRRS_M_TOP_100_BORROWER_SUMMARYTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
	            M_TOP_100_BORROWER_Summary_Entity.class, reportDate);

	    List<M_TOP_100_BORROWER_Manual_Summary_Entity1> dataList1 = queryEntities(
	            "SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE1 WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
	            M_TOP_100_BORROWER_Manual_Summary_Entity1.class, reportDate);

	    List<M_TOP_100_BORROWER_Manual_Summary_Entity2> dataList2 = queryEntities(
	            "SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE2 WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
	            M_TOP_100_BORROWER_Manual_Summary_Entity2.class, reportDate);

	    if (dataList == null || dataList.isEmpty()) {
	        logger.warn("No data found for report.");
	        return new byte[0];
	    }

	    // ✅ Safe fetch first record (since report is date-based)
	    M_TOP_100_BORROWER_Summary_Entity record = dataList.get(0);

	    M_TOP_100_BORROWER_Manual_Summary_Entity1 record1 =
	            (dataList1 != null && !dataList1.isEmpty())
	                    ? dataList1.get(0)
	                    : new M_TOP_100_BORROWER_Manual_Summary_Entity1();

	    M_TOP_100_BORROWER_Manual_Summary_Entity2 record2 =
	            (dataList2 != null && !dataList2.isEmpty())
	                    ? dataList2.get(0)
	                    : new M_TOP_100_BORROWER_Manual_Summary_Entity2();

	    // ✅ Load template
	    String templateDir = env.getProperty("output.exportpathtemp");
	    Path templatePath = Paths.get(templateDir, filename);

	    logger.info("Loading template from: {}", templatePath.toAbsolutePath());

	    if (!Files.exists(templatePath)) {
	        throw new FileNotFoundException("Template file not found at: " + templatePath);
	    }

	    try (InputStream is = Files.newInputStream(templatePath);
	         Workbook workbook = WorkbookFactory.create(is);
	         ByteArrayOutputStream out = new ByteArrayOutputStream()) {

	        Sheet sheet = workbook.getSheetAt(0);

	        // ✅ Excel row mapping
	        int excelStartRowIndex = 2; // R3 starts at row index 2
	        int startR = 3;
	        int endR = 102;

	        for (int r = startR; r <= endR; r++) {

	            int rowIndex = excelStartRowIndex + (r - startR);

	            Row row = sheet.getRow(rowIndex);
	            if (row == null) {
	                row = sheet.createRow(rowIndex);
	            }

	            // ✅ Write each borrower row
	            writeSingleBorrowerRow(sheet, rowIndex, r, record, record1, record2);
	        }

	        // ✅ Evaluate formulas
	        workbook.getCreationHelper().createFormulaEvaluator().evaluateAll();

	        workbook.write(out);

	        logger.info("Excel generated successfully. Size: {} bytes", out.size());

	        return out.toByteArray();
	    }
	}

	/**
	 * Helper method to write a single row (e.g., R03, R50) using Reflection. This
	 * replaces the 100 blocks of repetitive code.
	 */
	private void writeSingleBorrowerRow(Sheet sheet, int rowIndex, int rNumber,
			M_TOP_100_BORROWER_Summary_Entity summaryEntity, M_TOP_100_BORROWER_Manual_Summary_Entity1 manualEntity1,
			M_TOP_100_BORROWER_Manual_Summary_Entity2 manualEntity2) {

		Row row = sheet.getRow(rowIndex);
		if (row == null) {
			row = sheet.createRow(rowIndex);
		}

		// Construct the prefix, e.g., "R03", "R10", "R100"
		String prefix = "R" + rNumber;

		// Determine which manual entity to use.
		// Entity1 has R03 to R70. Entity2 has R71 to R102.
		Object currentManualEntity = (rNumber <= 70) ? manualEntity1 : manualEntity2;

		try {
			// --- Summary Entity Fields ---
			// Col B (1): PAN_NUM
			setCellValue(row, 1, getReflectedValue(summaryEntity, prefix + "_PAN_NUM"));
			// Col C (2): NAME_OF_BORROWER
			setCellValue(row, 2, getReflectedValue(summaryEntity, prefix + "_NAME_OF_BORROWER"));

			// --- Manual Entity Fields ---
			// Col D (3): GROUP_CODE
			setCellValue(row, 3, getReflectedValue(currentManualEntity, prefix + "_GROUP_CODE"));
			// Col E (4): GROUP_NAME
			setCellValue(row, 4, getReflectedValue(currentManualEntity, prefix + "_GROUP_NAME"));

			// --- Summary Entity Fields (Financials) ---
			// Col F (5): FBLIMIT
			setCellValue(row, 5, getReflectedValue(summaryEntity, prefix + "_FBLIMIT"));
			// Col G (6): FBOS
			setCellValue(row, 6, getReflectedValue(summaryEntity, prefix + "_FBOS"));

			// --- Manual Entity Fields ---
			// Col H (7): CRM
			setCellValue(row, 7, getReflectedValue(currentManualEntity, prefix + "_CRM"));

			// --- Summary Entity Fields ---
			// Col I (8): FB_EXPOSURE
			setCellValue(row, 8, getReflectedValue(summaryEntity, prefix + "_FB_EXPOSURE"));

			// --- Manual Entity Fields ---
			// Col J (9): NFBLT
			setCellValue(row, 9, getReflectedValue(currentManualEntity, prefix + "_NFBLT"));
			// Col K (10): NFBOS
			setCellValue(row, 10, getReflectedValue(currentManualEntity, prefix + "_NFBOS"));
			// Col L (11): CRM_2 (Note: check if your entity uses CRM_2 or just CRM for the
			// second one. Snippet said CRM_2)
			setCellValue(row, 11, getReflectedValue(currentManualEntity, prefix + "_CRM_2"));
			// Col M (12): NFB
			setCellValue(row, 12, getReflectedValue(currentManualEntity, prefix + "_NFB"));
			// Col N (13): BOND
			setCellValue(row, 13, getReflectedValue(currentManualEntity, prefix + "_BOND"));
			// Col O (14): CP
			setCellValue(row, 14, getReflectedValue(currentManualEntity, prefix + "_CP"));
			// Col P (15): EQUITY (Code said EQULITY - preserving typo from your entity)
			setCellValue(row, 15, getReflectedValue(currentManualEntity, prefix + "_EQULITY"));
			// Col Q (16): FOREX
			setCellValue(row, 16, getReflectedValue(currentManualEntity, prefix + "_FOREX"));
			// Col R (17): OTHERS
			setCellValue(row, 17, getReflectedValue(currentManualEntity, prefix + "_OTHERS"));
			// Col S (18): INT_BANK
			setCellValue(row, 18, getReflectedValue(currentManualEntity, prefix + "_INT_BANK"));
			// Col T (19): DERIVATIVE
			setCellValue(row, 19, getReflectedValue(currentManualEntity, prefix + "_DERIVATIVE"));

			// Note: Skipping Column U (20) based on your original code logic

			// --- Summary Entity Fields (Ratings) ---
			// Col V (21): IRAC
			setCellValue(row, 21, getReflectedValue(summaryEntity, prefix + "_IRAC"));
			// Col W (22): CR_RATING
			setCellValue(row, 22, getReflectedValue(summaryEntity, prefix + "_CR_RATING"));

		} catch (Exception e) {
			System.err.println("Error processing row " + prefix + ": " + e.getMessage());
			// Optionally log error but continue processing
		}
	}

	/**
	 * Reflection helper to get value from entity by field name. Expects standard
	 * getter naming: getFIELD_NAME()
	 */
	private Object getReflectedValue(Object entity, String fieldName) {
		if (entity == null)
			return null;
		try {
			// Construct getter name: "R03_PAN_NUM" -> "getR03_PAN_NUM"
			String getterName = "get" + fieldName;
			Method method = entity.getClass().getMethod(getterName);
			return method.invoke(entity);
		} catch (NoSuchMethodException e) {
			// Field might not exist (e.g. if naming convention varies slightly)
			// System.out.println("Method not found: get" + fieldName);
			return null;
		} catch (Exception e) {
			return null;
		}
	}

	/**
	 * Helper to safely set cell value based on type.
	 */
	private void setCellValue(Row row, int colIndex, Object value) {
		Cell cell = row.getCell(colIndex);
		if (cell == null) {
			cell = row.createCell(colIndex);
		}

		if (value == null) {
			cell.setCellValue("");
		} else if (value instanceof BigDecimal) {
			cell.setCellValue(((BigDecimal) value).doubleValue());
		} else if (value instanceof Double) {
			cell.setCellValue((Double) value);
		} else if (value instanceof Integer) {
			cell.setCellValue((Integer) value);
		} else {
			cell.setCellValue(value.toString());
		}
	}

