    // ------------------------------
    // Retrieves the list of archived (date, version) snapshots, most recent
    // version first - for populating a "pending resubmissions" style screen.
    // Mirrors BRRS_M_SFINP1_ReportService.getM_SFINP1Resub(), but
    // M_TOP_100_BORROWER_Archival_Summary_Entity only carries report_date /
    // report_version (no separate resub-date column), so each row here is
    // just [reportDate, reportVersion].
    // ------------------------------
    public List<Object[]> getM_TOP_100_BORROWERResub() {
        List<Object[]> resubList = new ArrayList<>();
        try {
            List<M_TOP_100_BORROWER_Archival_Summary_Entity> latestArchivalList = queryEntities(
                    "SELECT * FROM BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_SUMMARY WHERE REPORT_VERSION IS NOT NULL ORDER BY REPORT_VERSION DESC",
                    M_TOP_100_BORROWER_Archival_Summary_Entity.class);

            if (latestArchivalList != null && !latestArchivalList.isEmpty()) {
                for (M_TOP_100_BORROWER_Archival_Summary_Entity entity : latestArchivalList) {
                    resubList.add(new Object[] { entity.getReport_date(), entity.getReport_version() });
                }
                logger.info("Fetched {} record(s)", resubList.size());
            } else {
                logger.info("No archival data found.");
            }
        } catch (Exception e) {
            logger.error("Error fetching M_TOP_100_BORROWER Resub data: {}", e.getMessage(), e);
        }
        return resubList;
    }

    // ------------------------------
    // Looks up a single live Detail row by account number
    // ------------------------------
    public M_TOP_100_BORROWER_Detail_Entity findDetailByAcctnumber(String acctNumber) {
        String sql = "SELECT * FROM BRRS_M_TOP_100_BORROWER_DETAILTABLE WHERE ACCT_NUMBER = ?";
        List<M_TOP_100_BORROWER_Detail_Entity> list = queryEntities(sql, M_TOP_100_BORROWER_Detail_Entity.class,
                acctNumber);
        return list.isEmpty() ? null : list.get(0);
    }

    // ------------------------------
    // Saves a subset of editable fields on the live Detail entity
    // ------------------------------
    private void saveDetail(M_TOP_100_BORROWER_Detail_Entity entity) {
        String sql = "UPDATE BRRS_M_TOP_100_BORROWER_DETAILTABLE SET ACCT_NAME = ?, ACCT_BALANCE_IN_PULA = ? "
                + "WHERE ACCT_NUMBER = ?";
        jdbcTemplate.update(sql, entity.getAcct_name(), entity.getAcct_balance_in_pula(), entity.getAcct_number());
    }

    // ------------------------------
    // Finds the highest REPORT_VERSION already archived for a given date
    // ------------------------------
    private BigDecimal findMaxVersion(Date reportDate) {
        BigDecimal maxVersion = jdbcTemplate.queryForObject(
                "SELECT MAX(REPORT_VERSION) FROM BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_SUMMARY WHERE REPORT_DATE = ?",
                new Object[] { reportDate }, BigDecimal.class);
        return maxVersion != null ? maxVersion : BigDecimal.ZERO;
    }

    // ------------------------------
    // Promotes one archived (date, version) resub snapshot into the live
    // tables, replacing whatever is currently live for that date, so it can
    // be corrected using the report's normal live-edit tooling.
    // ------------------------------
    @Transactional
    public void promoteResubToLive(Date reportDate, BigDecimal version) {
        logger.info("Promoting M_TOP_100_BORROWER resub snapshot to live - date={}, version={}", reportDate,
                version);

        List<M_TOP_100_BORROWER_Archival_Summary_Entity> archSummaryList = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_SUMMARY WHERE REPORT_DATE = ? AND REPORT_VERSION = ?",
                M_TOP_100_BORROWER_Archival_Summary_Entity.class, reportDate, version);
        if (archSummaryList.isEmpty()) {
            throw new RuntimeException(
                    "No archival summary found for REPORT_DATE=" + reportDate + " REPORT_VERSION=" + version);
        }
        M_TOP_100_BORROWER_Archival_Summary_Entity archSummary = archSummaryList.get(0);

        List<M_TOP_100_BORROWER_Manual_Archival_Summary_Entity1> archManual1List = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_ARCHIVALTABLE_SUMMARY1 WHERE REPORT_DATE = ? AND REPORT_VERSION = ?",
                M_TOP_100_BORROWER_Manual_Archival_Summary_Entity1.class, reportDate, version);

        List<M_TOP_100_BORROWER_Manual_Archival_Summary_Entity2> archManual2List = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_ARCHIVALTABLE_SUMMARY2 WHERE REPORT_DATE = ? AND REPORT_VERSION = ?",
                M_TOP_100_BORROWER_Manual_Archival_Summary_Entity2.class, reportDate, version);

        List<M_TOP_100_BORROWER_Archival_Detail_Entity> archDetailList = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_DETAIL WHERE REPORT_DATE = ? AND DATA_ENTRY_VERSION = ?",
                M_TOP_100_BORROWER_Archival_Detail_Entity.class, reportDate, version.toString());

        // Replace whatever is currently live for this date with the archived snapshot.
        jdbcTemplate.update("DELETE FROM BRRS_M_TOP_100_BORROWER_DETAILTABLE WHERE REPORT_DATE = ?", reportDate);
        jdbcTemplate.update("DELETE FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE1 WHERE REPORT_DATE = ?",
                reportDate);
        jdbcTemplate.update("DELETE FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE2 WHERE REPORT_DATE = ?",
                reportDate);
        jdbcTemplate.update("DELETE FROM BRRS_M_TOP_100_BORROWER_SUMMARYTABLE WHERE REPORT_DATE = ?", reportDate);

        M_TOP_100_BORROWER_Summary_Entity liveSummary = new M_TOP_100_BORROWER_Summary_Entity();
        copyMatchingFields(archSummary, liveSummary);
        liveSummary.setReport_date(reportDate);
        liveSummary.setReport_version(version);
        insertEntityReflective("BRRS_M_TOP_100_BORROWER_SUMMARYTABLE", liveSummary);

        if (!archManual1List.isEmpty()) {
            M_TOP_100_BORROWER_Manual_Summary_Entity1 liveManual1 = new M_TOP_100_BORROWER_Manual_Summary_Entity1();
            copyMatchingFields(archManual1List.get(0), liveManual1);
            liveManual1.setReport_date(reportDate);
            liveManual1.setReport_version(version);
            insertEntityReflective("BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE1", liveManual1);
        }

        if (!archManual2List.isEmpty()) {
            M_TOP_100_BORROWER_Manual_Summary_Entity2 liveManual2 = new M_TOP_100_BORROWER_Manual_Summary_Entity2();
            copyMatchingFields(archManual2List.get(0), liveManual2);
            liveManual2.setReport_date(reportDate);
            liveManual2.setReport_version(version);
            insertEntityReflective("BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE2", liveManual2);
        }

        for (M_TOP_100_BORROWER_Archival_Detail_Entity archDetail : archDetailList) {
            M_TOP_100_BORROWER_Detail_Entity liveDetail = toLiveDetail(archDetail);
            liveDetail.setReport_date(reportDate);
            insertEntityReflective("BRRS_M_TOP_100_BORROWER_DETAILTABLE", liveDetail);
        }

        ServletRequestAttributes attrs = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
        if (attrs != null) {
            HttpServletRequest request = attrs.getRequest();
            String userid = (String) request.getSession().getAttribute("USERID");
            auditService.createBusinessAudit(userid, "PROMOTE_RESUB_TO_LIVE", "M_TOP_100_BORROWER Resub Promote to Live",
                    null, "BRRS_M_TOP_100_BORROWER_SUMMARYTABLE");
        }

        logger.info("M_TOP_100_BORROWER resub promote-to-live complete for date={} version={}", reportDate, version);
    }

    // ------------------------------
    // Finalises a live report that was promoted from resub: runs the
    // existing BRRS_M_TOP_100_BORROWER_SUMMARY_PROCEDURE for the report's own
    // date, then snapshots whatever the procedure leaves live back into the
    // archival tables as a new, incremented REPORT_VERSION (the procedure
    // itself always hardcodes version '1', so the increment has to happen
    // here in Java, not in the DB).
    // ------------------------------
    @Transactional
    public void finaliseResub(Date reportDate) {
        String formattedDate = new SimpleDateFormat("dd-MM-yyyy").format(reportDate);
        logger.info("Finalising M_TOP_100_BORROWER resub for date={} - running BRRS_M_TOP_100_BORROWER_SUMMARY_PROCEDURE({})",
                reportDate, formattedDate);

        // Run synchronously (not afterCommit) - the version-increment step below
        // depends on reading the procedure's output, so it must complete before we continue.
        jdbcTemplate.update("BEGIN BRRS_M_TOP_100_BORROWER_SUMMARY_PROCEDURE(?); END;", formattedDate);
        logger.info("BRRS_M_TOP_100_BORROWER_SUMMARY_PROCEDURE completed for date={}", reportDate);

        List<M_TOP_100_BORROWER_Summary_Entity> liveSummaryList = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_SUMMARYTABLE WHERE REPORT_DATE = ?",
                M_TOP_100_BORROWER_Summary_Entity.class, reportDate);
        if (liveSummaryList.isEmpty()) {
            throw new RuntimeException(
                    "BRRS_M_TOP_100_BORROWER_SUMMARY_PROCEDURE left no live summary row for REPORT_DATE=" + reportDate);
        }
        M_TOP_100_BORROWER_Summary_Entity liveSummary = liveSummaryList.get(0);

        List<M_TOP_100_BORROWER_Manual_Summary_Entity1> liveManual1List = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE1 WHERE REPORT_DATE = ?",
                M_TOP_100_BORROWER_Manual_Summary_Entity1.class, reportDate);

        List<M_TOP_100_BORROWER_Manual_Summary_Entity2> liveManual2List = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_MANUAL_SUMMARYTABLE2 WHERE REPORT_DATE = ?",
                M_TOP_100_BORROWER_Manual_Summary_Entity2.class, reportDate);

        List<M_TOP_100_BORROWER_Detail_Entity> liveDetailList = queryEntities(
                "SELECT * FROM BRRS_M_TOP_100_BORROWER_DETAILTABLE WHERE REPORT_DATE = ?",
                M_TOP_100_BORROWER_Detail_Entity.class, reportDate);

        BigDecimal newVersion = findMaxVersion(reportDate).add(BigDecimal.ONE);

        M_TOP_100_BORROWER_Archival_Summary_Entity archSummary = new M_TOP_100_BORROWER_Archival_Summary_Entity();
        copyMatchingFields(liveSummary, archSummary);
        archSummary.setReport_date(reportDate);
        archSummary.setReport_version(newVersion);
        insertEntityReflective("BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_SUMMARY", archSummary);

        if (!liveManual1List.isEmpty()) {
            M_TOP_100_BORROWER_Manual_Archival_Summary_Entity1 archManual1 = new M_TOP_100_BORROWER_Manual_Archival_Summary_Entity1();
            copyMatchingFields(liveManual1List.get(0), archManual1);
            archManual1.setReport_date(reportDate);
            archManual1.setReport_version(newVersion);
            insertEntityReflective("BRRS_M_TOP_100_BORROWER_MANUAL_ARCHIVALTABLE_SUMMARY1", archManual1);
        }

        if (!liveManual2List.isEmpty()) {
            M_TOP_100_BORROWER_Manual_Archival_Summary_Entity2 archManual2 = new M_TOP_100_BORROWER_Manual_Archival_Summary_Entity2();
            copyMatchingFields(liveManual2List.get(0), archManual2);
            archManual2.setReport_date(reportDate);
            archManual2.setReport_version(newVersion);
            insertEntityReflective("BRRS_M_TOP_100_BORROWER_MANUAL_ARCHIVALTABLE_SUMMARY2", archManual2);
        }

        for (M_TOP_100_BORROWER_Detail_Entity liveDetail : liveDetailList) {
            M_TOP_100_BORROWER_Archival_Detail_Entity archDetail = toArchivalDetail(liveDetail);
            archDetail.setReportDate(reportDate);
            archDetail.setDataEntryVersion(newVersion.toString());
            insertEntityReflective("BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_DETAIL", archDetail);
        }

        ServletRequestAttributes attrs = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
        if (attrs != null) {
            HttpServletRequest request = attrs.getRequest();
            String userid = (String) request.getSession().getAttribute("USERID");
            auditService.createBusinessAudit(userid, "FINALISE_RESUB", "M_TOP_100_BORROWER Resub Finalise", null,
                    "BRRS_M_TOP_100_BORROWER_ARCHIVALTABLE_SUMMARY");
        }

        logger.info("M_TOP_100_BORROWER resub finalised for date={} - new REPORT_VERSION={}", reportDate, newVersion);
    }
    
